"""Build server/engine.js: the app's own music logic (from src/Main.dc.html) as an ES module
for the Cloudflare Pages Functions (Claude connector + in-app assistant). Run by build.py."""
from pathlib import Path
ROOT = Path(__file__).resolve().parent.parent
src = (ROOT / 'src' / 'Main.dc.html').read_text(encoding='utf-8')
a = src.index('data-dc-script'); a = src.index('>', a) + 1; b = src.index('</script>', a)
head = '''// AUTO-GENERATED by server/build_engine.py from src/Main.dc.html. Do not edit by hand.
/* eslint-disable */
var __store = {};
var window = { localStorage: { getItem: function (k) { return null; }, setItem: function () {}, removeItem: function () {} }, scrollTo: function () {}, matchMedia: function () { return { matches: false, addEventListener: function () {} }; }, addEventListener: function () {}, removeEventListener: function () {}, location: { search: '', hash: '', href: '', pathname: '/' } };
var localStorage = window.localStorage, sessionStorage = window.localStorage;
var location = window.location;
var document = { addEventListener: function () {}, removeEventListener: function () {}, createElement: function () { return { style: {}, setAttribute: function () {}, appendChild: function () {}, addEventListener: function () {}, classList: { add: function () {}, remove: function () {} } }; }, body: { appendChild: function () {}, classList: { add: function () {}, remove: function () {}, contains: function () { return false; } } }, head: { appendChild: function () {} }, querySelector: function () { return null; }, querySelectorAll: function () { return []; }, getElementById: function () { return null; } };
class DCLogic { constructor(p) { this.props = p || {}; this.state = {}; } setState(o) { if (typeof o === 'function') o = o(this.state); Object.assign(this.state, o); } forceUpdate() {} }
'''
tail = '''
function __setLang(l) { CUR_LANG = l === 'es' ? 'es' : 'en'; }
export { SONGS, GENRE_REL, POOL, findIn, findPattern, scoreOf, sfx, extOf, FN, Component, parseChordName, parseChordList, chordName, mkSx, mkx, detect, detectAll, analyze, reharm, modRoutes, scalesForChord, substitutes, pcsOf, chordIvls, guitarFrets, spell, flatsFor, MOODS, RE_STYLES, SCALES, __setLang };
'''
(ROOT / 'server' / 'engine.js').write_text(head + src[a:b] + tail, encoding='utf-8')
print('server/engine.js', len(head + src[a:b] + tail), 'bytes')
